const env = $env || {};

const missing = [];
if (!String(env.GITLAB_WEBHOOK_SECRET || '').trim() && !String(env.GITLAB_WEBHOOK_SECRETS_JSON || '').trim() && !String(env.GITLAB_WEBHOOK_SECRETS_YAML || '').trim()) {
  missing.push('GITLAB_WEBHOOK_SECRET');
}
if (!String(env.N8N_GITLAB_API_BASE_URL || env.GITLAB_API_BASE_URL || '').trim()) missing.push('GITLAB_API_BASE_URL');
if (!String(env.N8N_GITLAB_TOKEN || env.GITLAB_TOKEN || env.GITLAB_ADMIN_TOKEN || '').trim()) missing.push('GITLAB_TOKEN');

return [{
  json: {
    ok: missing.length === 0,
    status_code: missing.length === 0 ? 200 : 424,
    missing,
    tip: 'GitLab Project Hook は /webhook/gitlab/cir/auto_label に issues_events=true で向けてください。'
  }
}];
